{"hypotheses": [
  {
    "name": "Quality-Momentum Divergence",
    "mechanism": "Combining operating profitability (OperProf), 12-month momentum (Mom12m), and net equity financing (NetEquityFinance) captures stocks with both strong fundamentals and positive price trends, while penalizing those issuing equity. This composite exploits the tendency for quality momentum stocks to outperform, especially when not diluted by equity issuance.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": 1.0, "primitive": "Mom12m"},
        {"weight": -1.0, "primitive": "NetEquityFinance"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "OperProf", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 1.0,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Defensive Value in Volatile Regimes",
    "mechanism": "Combining book-to-market (BM), low beta (Beta), and Amihud illiquidity (Illiquidity) in high VIX regimes targets undervalued, low-risk, and less liquid stocks, which tend to be defensive and outperform during market stress when risk aversion is elevated.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": -1.0, "primitive": "Beta"},
        {"weight": 0.5, "primitive": "Illiquidity"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Earnings Revision-Volatility Spread",
    "mechanism": "Stocks with positive analyst revisions (AnalystRevision) and low realized volatility (RealizedVol), but high forecast dispersion (ForecastDispersion), reflect underappreciated improvement amid uncertainty. This composite exploits the market's slow reaction to positive news in volatile, controversial stocks.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AnalystRevision"},
        {"weight": -0.5, "primitive": "RealizedVol"},
        {"weight": 0.5, "primitive": "ForecastDispersion"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "correlation", "primitive": "AnalystRevision", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "mega", "direction": "weaker"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Asset Growth Contrarian in Down Markets",
    "mechanism": "Combining negative asset growth (AssetGrowth), high payout yield (PayoutYield), and short-term reversal (STreversal) in down markets captures firms returning capital and rebounding from oversold conditions, exploiting overreaction and capital discipline when sentiment is poor.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AssetGrowth"},
        {"weight": 1.0, "primitive": "PayoutYield"},
        {"weight": 0.5, "primitive": "STreversal"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Intangible-Driven Momentum",
    "mechanism": "Firms with high intangible-adjusted earnings-to-price (IntanEP), strong intermediate momentum (IntMom), and low share issuance (ShareIss1Y) benefit from persistent innovation and capital discipline, which the market underestimates, especially in knowledge-driven sectors.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "IntanEP"},
        {"weight": 1.0, "primitive": "IntMom"},
        {"weight": -0.5, "primitive": "ShareIss1Y"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "IntanEP", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Liquidity-Adjusted Reversal",
    "mechanism": "Combining short-term reversal (STreversal), Amihud illiquidity (Illiquidity), and bid-ask spread (BidAskSpread) targets stocks that have recently underperformed and are illiquid, where price pressure and liquidity shocks drive temporary mispricings that subsequently reverse.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "STreversal"},
        {"weight": 0.5, "primitive": "Illiquidity"},
        {"weight": 0.5, "primitive": "BidAskSpread"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "correlation", "primitive": "STreversal", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 12
  },
  {
    "name": "Profitability-Volatility Spread",
    "mechanism": "Stocks with high gross profitability (GP), low realized volatility (RealizedVol), and high volume trend (VolumeTrend) combine persistent earnings power, stability, and investor attention, which together predict outperformance as the market underreacts to stable, profitable firms with rising interest.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "GP"},
        {"weight": -0.5, "primitive": "RealizedVol"},
        {"weight": 0.5, "primitive": "VolumeTrend"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "GP", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Analyst Disagreement Defensive",
    "mechanism": "Stocks with high forecast dispersion (ForecastDispersion), low beta (Beta), and high cash to assets (Cash) are often overlooked during periods of high uncertainty. This composite exploits the market's tendency to underprice defensiveness and optionality in controversial, cash-rich, low-risk firms.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ForecastDispersion"},
        {"weight": -1.0, "primitive": "Beta"},
        {"weight": 0.5, "primitive": "Cash"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 18
  }
]}
